#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    void meow() const {
        cout << name << "：喵～" << endl;
    }
};

class Kitten : public Cat {
public:
    void wag() const {
        cout << name << " 摇起了尾巴" << endl;
    }
};

int main() {
    string name;
    cin >> name;

    Kitten k;
    k.name = name;
    k.meow();
    k.wag();
    return 0;
}
